<script setup lang="ts">
import { computed, ref, useId, watch } from 'vue'
import { TabsRoot, TabsList, TabsTrigger, TabsContent } from 'reka-ui'
const controlId = useId()
const tab = ref('controls'), intensity = ref(64), enabled = ref(true), pressed = ref(false)
const ticks = Array.from({length:31},(_,i)=>{const a=(i*8-120)*Math.PI/180;return {x1:100+Math.sin(a)*75,y1:100-Math.cos(a)*75,x2:100+Math.sin(a)*(i%5===0?64:69),y2:100-Math.cos(a)*(i%5===0?64:69)}})
watch(enabled, value => { if (!value) pressed.value = false })
const angle = computed(()=>Number(intensity.value)*2.4-120)
</script>
